extra_menus.build_method:
juce::PopupMenu buildDrumMapMenu()
    {
        juce::PopupMenu menu;
        menu.addItem({ID_BASE} + 1, "Load Drum Map...");
        menu.addItem({ID_BASE} + 2, "Reload", processorRef.hasDrumMapFile());
        menu.addItem({ID_BASE} + 3, "Use Built-in Default");
        menu.addSeparator();
        menu.addItem({ID_BASE} + 4, "Current: " + processorRef.drumMapName(), false);
        return menu;
    }

extra_menus.select_method:
void handleDrumMapMenuSelection(const int menuItemID)
    {
        if (menuItemID == {ID_BASE} + 1)
        {
            juce::FileChooser chooser("Load Drum Map", processorRef.drumMapBrowseStart(), "*.json");
            if (chooser.browseForFileToOpen())
            {
                processorRef.loadDrumMapFile(chooser.getResult());
            }
        }
        else if (menuItemID == {ID_BASE} + 2)
        {
            processorRef.reloadDrumMap();
        }
        else if (menuItemID == {ID_BASE} + 3)
        {
            processorRef.useDefaultDrumMap();
        }
    }

extra_processor_methods:
void pollAnalysisMetronome() {
        const auto isOn = [this](const char* id) { const auto* v = m_parameters.getRawParameterValue(id); return v != nullptr && v->load() > 0.5f; };
        const bool analysisOn = isOn("analysisMode");
        const bool metronomeOn = isOn("onOff");
        const auto setMetronome = [this](const bool on) { if (auto* p = m_parameters.getParameter("onOff")) { p->setValueNotifyingHost(on ? 1.f : 0.f); } };
        if (m_analysisStartedMetronome && !metronomeOn)
        {
            m_analysisStartedMetronome = false;
        }
        if (analysisOn == m_prevAnalysisOn)
        {
            return;
        }
        m_prevAnalysisOn = analysisOn;
        if (analysisOn && pluginRunner && !pluginRunner->isHostSynced() && !metronomeOn)
        {
            m_analysisStartedMetronome = true;
            setMetronome(true);
        }
        else if (!analysisOn && m_analysisStartedMetronome)
        {
            m_analysisStartedMetronome = false;
            setMetronome(false);
        }
    }

void pollAnalysisAutoStop() {
        if (!pluginRunner || !pluginRunner->consumeAnalysisAutoStopped())
        {
            return;
        }
        if (auto* p = m_parameters.getParameter("analysisMode"))
        {
            p->setValueNotifyingHost(0.f);
        }
    }

[[nodiscard]] std::optional<juce::String> pollStatusText() {
        std::string text = pluginRunner ? pluginRunner->analysisStatusText() : std::string{};
        if (text.empty())
        {
            text = !m_drumMapError.empty() ? m_drumMapError : (pluginRunner ? pluginRunner->midiMonitorText() : std::string{});
        }
        if (text == m_lastAnalysisStatus)
        {
            return std::nullopt;
        }
        m_lastAnalysisStatus = text;
        return juce::String(text);
    }

void loadDrumMapFile(const juce::File& file) {
        if (!pluginRunner)
        {
            return;
        }
        m_drumMapPath = file;
        if (!file.existsAsFile())
        {
            m_drumMapError = "Drum map not found: " + file.getFullPathName().toStdString();
            return;
        }
        const auto error = pluginRunner->setDrumMapJson(file.loadFileAsString().toStdString());
        m_drumMapError = error ? "Drum map " + file.getFileName().toStdString() + ": " + *error : std::string{};
        if (!error)
        {
            DrumMapStore::saveFile(file);
        }
    }

void useDefaultDrumMap() {
        if (pluginRunner)
        {
            pluginRunner->useDefaultDrumMap();
        }
        m_drumMapPath = juce::File{};
        m_drumMapError.clear();
        DrumMapStore::clear();
    }

void pollAnalysisReport() {
        if (!pluginRunner || !pluginRunner->consumeAnalysisReportReady())
        {
            return;
        }
        auto dir = juce::File::getSpecialLocation(juce::File::userDocumentsDirectory).getChildFile("DrumTrainer Analysis");
        dir.createDirectory();
        const auto stem = pluginRunner->analysisFileStem();
        const auto prefix = stem.empty() ? juce::String("analysis-") : "analysis-" + juce::String(stem) + "-";
        const auto file = dir.getChildFile(prefix + juce::Time::getCurrentTime().formatted("%Y%m%d-%H%M%S") + ".html");
        file.replaceWithText(pluginRunner->buildAnalysisReportHtml());
        juce::URL(file).launchInDefaultBrowser();
    }

[[nodiscard]] std::vector<DrumDisplay::DisplayHit> takeDisplayHits() {
        std::vector<DrumDisplay::DisplayHit> hits;
        if (pluginRunner)
        {
            pluginRunner->readDisplayHits(m_displayReadIndex, [&hits](const DrumDisplay::DisplayHit& hit) { hits.push_back(hit); });
        }
        return hits;
    }
